    eys.forEach(function (v, i) { out["ey" + (i + 1)] = fl ? (i === 0 ? earnTotal : 0) : v; });
    out.earned_total = earnTotal;
    out.earned_measured = earnMeasured;
    out.earned_advance = earnAdvance;
